<?php declare(strict_types=1);
require dirname(__DIR__).'/native/bootstrap.php';
use Kulturhus\Native\TestSupport;
use Kulturhus\Native\Shared\{Access,Db};
use Kulturhus\Native\Cms\{Pages,PublishedEvents};
use Kulturhus\Native\Events\{Workflow,Eventbrite};
use Kulturhus\Native\Web\Settings\{Workspace,EventWorkflowPanel};

$db=TestSupport::db();TestSupport::seed($db);
Kulturhus\Native\Communication\Schema::install($db);Kulturhus\Native\Cms\Schema::install($db);
$checks=0;
$check=static function(bool $ok,string $label)use(&$checks):void{if(!$ok)throw new RuntimeException($label);$checks++;};
$deny=static function(callable $action,string $label)use($check):void{try{$action();}catch(DomainException|InvalidArgumentException){$check(true,$label);return;}throw new RuntimeException($label);};
$access=new Access($db,'admin');$club=$access->club();$store=new Workflow($db,$access);$pages=new Pages($db,$access);
$original=$pages->save(['title'=>'Interner Termin, öffentliche Website','slug'=>'veranstaltungen/vereinstermin','template'=>'event','event_start'=>'2050-10-25T19:00','event_timezone'=>'Europe/Berlin','event_location'=>'Vereinssaal','body'=>'Eigener Inhalt']);
$pages->publish($original['id'],$original['version']);
$raw=['id'=>'1008','name'=>['text'=>'Eventbrite-Original'],'description'=>['text'=>'Eigener synthetischer Import'],'start'=>['utc'=>'2050-10-25T18:00:00Z','timezone'=>'Europe/Berlin'],'end'=>['utc'=>'2050-10-25T20:00:00Z'],'venue'=>['name'=>'Saal'],'status'=>'live','url'=>'https://www.eventbrite.de/e/1008'];
$events=new Eventbrite($db,$access);$import=$events->import([Eventbrite::normalize($raw)]);
$snapshot=static function()use($db):array{$out=[];foreach(['khcms_pages','khcms_revisions','khcms_events','native_event_sources','native_users','native_grants']as$table)$out[$table]=$db->query('SELECT * FROM '.$table.' ORDER BY 1,2')->fetchAll();return $out;};
$before=$snapshot();
$check($store->get()===['version'=>0,'source'=>'eventbrite','tickets'=>'eventbrite','payment'=>'none','automatic_publication'=>false],'unconfigured installation preserves old direct Eventbrite workflow without publishing');
$choice=['source'=>'facebook','tickets'=>'eventbrite','payment'=>'none','automatic_publication'=>false];
$state=$store->save($choice,0);$check($state['version']===1&&$state['source']==='facebook'&&$state['tickets']==='eventbrite','Eventbrite via Facebook selectable');
$deny(fn()=>$store->requireSource('eventbrite'),'old provider cannot sync after selection');
$check($store->requireSource('facebook')===$state,'selected provider allowed');
$choice=['source'=>'facebook','tickets'=>'native','payment'=>'sumup','automatic_publication'=>true];
$state=$store->save($choice,1);$check($state['tickets']==='native'&&$state['payment']==='sumup'&&$state['automatic_publication'],'manual Facebook route with native SumUp tickets and explicit automatic publication selectable');
$choice['payment']='stripe';$state=$store->save($choice,2);$check($state['payment']==='stripe','payment provider switch independent from event source');
$choice['source']='local';$choice['payment']='none';$choice['automatic_publication']=false;$store->save($choice,3);
$check($snapshot()===$before,'switches preserve every original page, revision, event, provider identity and actor row');
$check(count((new PublishedEvents($db,$club))->between('2050-10-01','2050-11-01'))===1,'own public website event stays visible without Facebook');
$choice['tickets']='none';$state=$store->save($choice,4);$check($state['tickets']==='none','events without ticket sales supported');
$beforeState=$store->get();$deny(fn()=>$store->save($choice,3),'stale setting cannot replace current choice');$check($store->get()===$beforeState,'stale write preserves current version and choices');
foreach(['source'=>['',null,[],true,'unknown'],'tickets'=>['',null,[],'stripe'],'payment'=>['',null,[],'reader']]as$field=>$badValues)foreach($badValues as$value){$bad=$choice;$bad[$field]=$value;$deny(fn()=>$store->save($bad,5),'malformed '.$field.' rejected');}
foreach([0,'1',null,[]]as$value){$bad=$choice;$bad['automatic_publication']=$value;$deny(fn()=>$store->save($bad,5),'publication must be boolean');}
$deny(fn()=>$store->save($choice,-1),'negative version rejected');$deny(fn()=>$store->save($choice,2147483647),'version overflow rejected');
foreach(['reader','editor']as$id)$deny(fn()=>(new Workflow($db,new Access($db,$id)))->save($choice,0),'role cannot change provider settings');
$check((new Workflow($db,new Access($db,'outsider')))->get()['version']===0,'other club has separate defaults');
$deny(fn()=>EventWorkflowPanel::input(['automatic_publication'=>[]]),'malformed form choice rejected');
$panel=EventWorkflowPanel::render($db,$access,'synthetic-workflow-csrf');
$check(str_contains($panel,'name="csrf" value="synthetic-workflow-csrf"')&&str_contains($panel,'SumUp Online-Checkout')&&str_contains($panel,'Stripe Checkout'),'native compact form exposes both online providers and CSRF');
$deny(fn()=>EventWorkflowPanel::render($db,new Access($db,'reader'),'csrf'),'reader cannot view editable provider form');
$workspace=new Workspace($db,$access,'/unused','synthetic-workflow-csrf');
$post=['csrf'=>'wrong','operation'=>'event-workflow','version'=>'5','source'=>'eventbrite','tickets'=>'native','payment'=>'sumup'];
$deny(fn()=>$workspace->action($post),'real settings action rejects foreign CSRF before mutation');
$post['csrf']='synthetic-workflow-csrf';$workspace->action($post);$check($store->get()['version']===6&&$store->get()['source']==='eventbrite','real settings action saves independently switchable source');
$raw['id']='1009';$current=$store->get();$store->save($choice,6);
$deny(fn()=>$events->import([Eventbrite::normalize($raw)],$club,$current['version']),'in-flight sync cannot write after workflow changed');
$check($snapshot()===$before,'rejected late sync retains all originals without new page');
$choice['source']='eventbrite';$store->save($choice,7);$state=$store->get();
$check($events->import([Eventbrite::normalize(array_replace($raw,['id'=>'1008']))],$club,$state['version'])[0]['status']==='unchanged','switching back keeps original source and page identity');
$choice['automatic_publication']=true;$state=$store->save($choice,8);
$raw['id']='1010';$auto=$events->import([Eventbrite::normalize($raw)],$club,$state['version']);
$check($auto[0]['status']==='published'&&$pages->get($auto[0]['id'])['published_revision']!==null,'explicit automatic publication uses actual website publication service');
Db::run($db,"DELETE FROM native_grants WHERE actor_id='admin' AND module='website' AND capability='publish'");
$choice['automatic_publication']=true;$deny(fn()=>$store->save($choice,9),'manage without publish cannot activate automatic publication');
$check($store->get()['version']===9,'denied publication authority does not increment settings');
$count=count($pages->list());$raw['id']='1011';$deny(fn()=>$events->import([Eventbrite::normalize($raw)],$club,9),'revoked publication authority rolls automatic import back');
$check(count($pages->list())===$count,'failed automatic publication leaves no partial new event');
$history=$db->query('SELECT version,payload_json,actor_id FROM native_event_workflow_history WHERE club_id='.$db->quote($club).' ORDER BY version')->fetchAll();
$check(count($history)===9&&$history[0]['actor_id']==='admin'&&json_decode($history[1]['payload_json'],true)['payment']==='sumup','exact prior provider choices retained in versioned history');
echo json_encode(['checks'=>$checks,'status'=>'passed','live_transport'=>false],JSON_THROW_ON_ERROR)."\n";
